{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Ensure VNET subnet is configured with a Network Security Group (NSG)",
      "resource": "azurerm_subnet.private_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet 'smart-manufacturing-iot-monitoring-platform-subnet-private' is not associated with a Network Security Group (NSG), potentially exposing it to unauthorized access."
    }
  ],
  "patched_code": "resource "azurerm_subnet" "private_subnet" {
  name                 = "smart-manufacturing-iot-monitoring-platform-subnet-private"
  resource_group_name  = azurerm_resource_group.smart_manufacturing.name
  virtual_network_name = azurerm_virtual_network.smart_manufacturing_vnet.name
  address_prefixes     = ["10.0.2.0/24"]
}

resource "azurerm_network_security_group" "private_subnet_nsg" {
  name                = "smart-manufacturing-iot-monitoring-platform-subnet-private-nsg"
  location            = azurerm_resource_group.smart_manufacturing.location
  resource_group_name = azurerm_resource_group.smart_manufacturing.name

  security_rule {
    name                       = "default_rule"
    priority                   = 1000
    direction                  = "Inbound"
    access                     = "Deny"
    protocol                   = "*"
    source_port_range          = "*"
    destination_port_range     = "*"
    source_address_prefix      = "*"
    destination_address_prefix = "*"
  }
}

resource "azurerm_subnet_network_security_group_association" "private_subnet_nsg_assoc" {
  subnet_id                 = azurerm_subnet.private_subnet.id
  network_security_group_id = azurerm_network_security_group.private_subnet_nsg.id
}",
  "fix_summary": "Created a new Network Security Group (NSG) with a default deny-all rule and associated it with the 'private_subnet' subnet to restrict unauthorized access."
}
